                    <div class="data-item"><strong>轮回天数:</strong> <span class="value value-display" ref="loopDaysValueRef">{{ state.userStatus.loopDays || 'N/A' }}</span></div>
                    <div class="data-item"><strong>体力:</strong> <progress-bar :value="state.userStatus.hp" :max="100" color="var(--progress-my-hp-bar)" /></div>
                    <div class="data-item"><strong>魔力:</strong> <progress-bar :value="state.userStatus.mp" :max="100" color="var(--progress-my-mp-bar)" /></div>
                    <div class="data-item"><strong>灵魂:</strong> <progress-bar :value="state.userStatus.soulPurity" :max="100" color="var(--progress-my-soul-bar)" text-color="#555" /></div>
                    <div class="data-item"><strong>服装:</strong> <span class="value">{{ state.userStatus.clothing || 'N/A' }}</span></div>
                    <div class="data-item"><strong>状态:</strong> <span class="value">{{ state.userStatus.condition || 'N/A' }}</span></div>
                    <div class="data-item"><strong>动作:</strong> <span class="value">{{ state.userStatus.action || 'N/A' }}</span></div>
